-- #1671 - Image Hub phase 1b: remember which Merqify Image Hub asset a store image was copied from,
-- and the hub usage recorded for it, so removing the image can also remove the usage in the hub.
--
-- HAND-AUTHORED, not generated by `prisma migrate dev --create-only`: that command refuses on the
-- dev database (#895) and offers only `migrate reset`.
--
-- Purely additive: four nullable TEXT columns, no default, no index. Every existing row stays NULL
-- (an image that did not come from the hub). The ids are the hub's UUIDs, kept as plain text with no
-- foreign key because the hub is a separate service with its own database.

-- AlterTable
ALTER TABLE "CategoryAsset" ADD COLUMN     "hubAssetId" TEXT,
ADD COLUMN     "hubUsageId" TEXT;

-- AlterTable
ALTER TABLE "ProductImage" ADD COLUMN     "hubAssetId" TEXT,
ADD COLUMN     "hubUsageId" TEXT;
